// src/components/pages/Login.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { motion } from "framer-motion";

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (!email || !password) {
      setError("Please enter email and password.");
      return;
    }

    setBusy(true);
    try {
      // adjust URL to match your backend
      const res = await axios.post(
        "http://localhost:8080/api/auth/login",
        { email, password },
        { headers: { "Content-Type": "application/json" }, timeout: 20000 }
      );

      // expected response: { token: "..." } or { success: true, token: "..." , user: {...}}
      const token = res?.data?.token || res?.data?.accessToken || null;
      if (!token) {
        // backend responded 200 but no token — treat as error
        setError("Login succeeded but no token returned from server.");
        setBusy(false);
        return;
      }

      // store token and optionally user info
      localStorage.setItem("token", token);
      if (res.data.user) localStorage.setItem("user", JSON.stringify(res.data.user));

      // navigate to home or protected dashboard
      navigate("/"); // or navigate("/dashboard")
    } catch (err) {
      console.error("Login error:", err);
      // network / server errors
      if (err.response) {
        // server responded with status outside 2xx
        const msg = err.response.data?.message || err.response.statusText || "Login failed";
        setError(`Error: ${msg}`);
      } else if (err.request) {
        setError("No response from server. Is backend running?");
      } else {
        setError("Login failed: " + err.message);
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background to-gray-100 p-6">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.45 }}
        className="w-full max-w-md bg-white rounded-2xl shadow-xl p-8 border border-gray-100"
      >
        <h2 className="text-2xl font-serif text-primary mb-4 text-center">Welcome Back</h2>

        {error && (
          <div className="bg-red-50 text-red-700 p-3 rounded mb-4">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <label className="block">
            <span className="text-sm text-gray-600">Email</span>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="mt-1 block w-full border rounded px-3 py-2 outline-none focus:ring-2 focus:ring-secondary"
              placeholder="you@example.com"
              required
            />
          </label>

          <label className="block">
            <span className="text-sm text-gray-600">Password</span>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 block w-full border rounded px-3 py-2 outline-none focus:ring-2 focus:ring-secondary"
              placeholder="••••••••"
              required
            />
          </label>

          <button
            type="submit"
            disabled={busy}
            className={`w-full py-2 rounded-md text-white font-medium ${
              busy ? "bg-blue-400 cursor-not-allowed" : "bg-secondary hover:bg-primary"
            }`}
          >
            {busy ? "Logging in…" : "Login"}
          </button>
        </form>

        <p className="text-center text-sm text-gray-500 mt-4">
          Don't have an account?{" "}
          <button
            onClick={() => navigate("/signup")}
            className="text-secondary font-semibold hover:text-primary"
          >
            Sign up
          </button>
        </p>
      </motion.div>
    </div>
  );
}
